package net.civeira.phylax.feature.identity.consentpurpose.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.consentpurpose.domain.ConsentPurpose;
import net.civeira.phylax.feature.identity.consentpurpose.domain.valueobject.DescriptionVO;

class DescriptionValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of description of consent purpose")
  void test_description_value_holder_assign_plain_value() {
    Object holder = new Object();
    DescriptionValueHolder<Object> value = new DescriptionValueHolder<>(holder);
    Assertions.assertSame(holder, value.description("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getDescriptionValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getDescription().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of description of consent purpose")
  void test_description_value_holder_assign_value_object() {
    Object holder = new Object();
    DescriptionValueHolder<Object> value = new DescriptionValueHolder<>(holder);
    DescriptionVO vo = DescriptionVO.from("one");
    Assertions.assertFalse(value.getDescriptionValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.description(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getDescriptionValue().orElseThrow());
    Assertions.assertSame(holder, value.description(Optional.empty()));
    Assertions.assertFalse(value.getDescriptionValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.description(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDescriptionValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of description of consent purpose against the original")
  void test_description_value_holder_read() {
    Object holder = new Object();
    DescriptionValueHolder<Object> value = new DescriptionValueHolder<>(holder);
    DescriptionVO vo = DescriptionVO.from("one");
    DescriptionVO other = DescriptionVO.from("one");
    ConsentPurpose original = Mockito.mock(ConsentPurpose.class);
    Mockito.when(original.getDescriptionValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDescription(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readDescription(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.description(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDescription(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDescription(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of description of consent purpose")
  void test_description_value_holder_unset() {
    Object holder = new Object();
    DescriptionValueHolder<Object> value = new DescriptionValueHolder<>(holder);
    DescriptionVO vo = DescriptionVO.from("one");
    value.description(vo);
    Assertions.assertSame(holder, value.unsetDescriptionIfMatches("description_other"));
    Assertions.assertTrue(value.getDescriptionValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetDescriptionIfMatches("description"));
    Assertions.assertFalse(value.getDescriptionValue().isPresent(),
        "The field name must clear the value");
    value.description(vo);
    Assertions.assertSame(holder, value.unsetDescription());
    Assertions.assertFalse(value.getDescriptionValue().isPresent(), "Unset must clear the value");
  }
}
